CustomField.formula:
if ( isblank( Monday_Time_In__c) && isblank ( Monday_Time_Out__c), 0,

if ( isblank(Monday_Lunch_End__c) && isblank(Monday_Lunch_Start__c),

( 

(floor(Monday_Time_Out_Proxy__c) + (Monday_Time_Out_Proxy__c - floor(Monday_Time_Out_Proxy__c))/60*100)

- (floor(Monday_Time_In_Proxy__c) + (Monday_Time_In_Proxy__c - floor(Monday_Time_In_Proxy__c))/60*100)

),

( 

(floor( Monday_Lunch_Start_Proxy__c ) + (Monday_Lunch_Start_Proxy__c - floor(Monday_Lunch_Start_Proxy__c ))/60*100)

- (floor(Monday_Time_In_Proxy__c) + (Monday_Time_In_Proxy__c - floor(Monday_Time_In_Proxy__c))/60*100)

)

))
